<?php
require_once '_bootstrap.php'; require_admin_permission('catalog.manage'); $db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
 try {
  if($action==='country_create'){
   $name=trim($_POST['country_name']??''); $iso=strtoupper(trim($_POST['iso_code']??'')); $currency=strtoupper(trim($_POST['currency_code']??''));
   if($name===''||!preg_match('/^[A-Z]{2,3}$/',$iso)||!preg_match('/^[A-Z]{3}$/',$currency)) throw new RuntimeException('Enter a country name, a 2-3 letter ISO code, and a 3-letter currency code.');
   $image=admin_upload_image('country_image'); $s=$db->prepare('INSERT INTO countries(name,iso_code,currency_code,image) VALUES(?,?,?,?)'); $s->bind_param('ssss',$name,$iso,$currency,$image);
   if(!$s->execute()) throw new RuntimeException('That country or ISO code already exists.'); admin_audit($db,'create','country',(string)$db->insert_id,$name);
  } elseif($action==='country_update'){
   $name=trim($_POST['country_name']??'');$iso=strtoupper(trim($_POST['iso_code']??''));$currency=strtoupper(trim($_POST['currency_code']??''));
   if(!$id||$name===''||!preg_match('/^[A-Z]{2,3}$/',$iso)||!preg_match('/^[A-Z]{3}$/',$currency)) throw new RuntimeException('Enter a country name, a 2-3 letter ISO code, and a 3-letter currency code.');
   $s=$db->prepare('SELECT image FROM countries WHERE id=?');$s->bind_param('i',$id);$s->execute();$current=$s->get_result()->fetch_assoc();if(!$current)throw new RuntimeException('Country not found.');
   $image=admin_upload_image('country_image')?:$current['image'];$s=$db->prepare('UPDATE countries SET name=?,iso_code=?,currency_code=?,image=? WHERE id=?');$s->bind_param('ssssi',$name,$iso,$currency,$image,$id);
   if(!$s->execute())throw new RuntimeException('That country name or ISO code is already in use.');admin_audit($db,'update','country',(string)$id,$name);
  } elseif(in_array($action,['country_enable','country_disable'],true)){
   $status=$action==='country_enable'?'active':'disabled'; $s=$db->prepare('UPDATE countries SET status=? WHERE id=?'); $s->bind_param('si',$status,$id); $s->execute();
   if($status==='disabled'){$s=$db->prepare("UPDATE states SET status='disabled' WHERE country_id=?");$s->bind_param('i',$id);$s->execute();} admin_audit($db,$status,'country',(string)$id);
  } elseif($action==='country_delete'){
   $s=$db->prepare('SELECT c.name,COUNT(s.id) region_count FROM countries c LEFT JOIN states s ON s.country_id=c.id WHERE c.id=? GROUP BY c.id');$s->bind_param('i',$id);$s->execute();$country=$s->get_result()->fetch_assoc();
   if(!$country) throw new RuntimeException('Country not found.');
   if((int)$country['region_count']>0) throw new RuntimeException($country['name'].' has '.$country['region_count'].' regions. Move or delete those regions before deleting the country.');
   $s=$db->prepare('DELETE FROM countries WHERE id=?');$s->bind_param('i',$id);$s->execute();admin_audit($db,'delete','country',(string)$id,$country['name']);
  } elseif($action==='region_create'){
   $countryId=(int)($_POST['country_id']??0); $name=trim($_POST['name']??''); $type=$_POST['type']??'state';
   if(!$countryId||$name===''||!in_array($type,['state','union_territory','province','territory'],true)) throw new RuntimeException('Select a country and complete the region details.');
   $image=admin_upload_image('region_image'); if(!$image) throw new RuntimeException('Choose an image for the region.');
   $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).'-'.substr(bin2hex(random_bytes(2)),0,4); $s=$db->prepare('INSERT INTO states(country_id,name,slug,type,image) VALUES(?,?,?,?,?)'); $s->bind_param('issss',$countryId,$name,$slug,$type,$image);
   if(!$s->execute()) throw new RuntimeException('That region already exists.'); admin_audit($db,'create','region',(string)$db->insert_id,$name);
  } elseif($action==='region_update'){
   $countryId=(int)($_POST['country_id']??0);$name=trim($_POST['name']??'');$type=$_POST['type']??'state';
   if(!$id||!$countryId||$name===''||!in_array($type,['state','union_territory','province','territory'],true))throw new RuntimeException('Select a country and complete the region details.');
   $s=$db->prepare('SELECT image FROM states WHERE id=?');$s->bind_param('i',$id);$s->execute();$current=$s->get_result()->fetch_assoc();if(!$current)throw new RuntimeException('Region not found.');
   $image=admin_upload_image('region_image')?:$current['image'];$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).'-'.$id;
   $s=$db->prepare('UPDATE states SET country_id=?,name=?,slug=?,type=?,image=? WHERE id=?');$s->bind_param('issssi',$countryId,$name,$slug,$type,$image,$id);if(!$s->execute())throw new RuntimeException('That region name is already in use.');admin_audit($db,'update','region',(string)$id,$name);
  } elseif(in_array($action,['enable','disable'],true)){
   $status=$action==='enable'?'active':'disabled'; $s=$db->prepare('UPDATE states SET status=? WHERE id=?'); $s->bind_param('si',$status,$id); $s->execute();
   if($status==='disabled'){$s=$db->prepare("UPDATE packages SET status='archived' WHERE state_id=?");$s->bind_param('i',$id);$s->execute();} admin_audit($db,$action,'region',(string)$id);
  } elseif($action==='delete'){
   $s=$db->prepare('SELECT COUNT(*) total FROM packages WHERE state_id=?');$s->bind_param('i',$id);$s->execute();if((int)$s->get_result()->fetch_assoc()['total'])throw new RuntimeException('This region has packages. Disable it instead, or remove its packages first.');
   $s=$db->prepare('DELETE FROM destinations WHERE state_id=?');$s->bind_param('i',$id);$s->execute();$s=$db->prepare('DELETE FROM states WHERE id=?');$s->bind_param('i',$id);$s->execute();admin_audit($db,'delete','region',(string)$id);
  }
  redirect_with_message('regions.php','Catalog action completed.');
 } catch(Throwable $e){redirect_with_message('regions.php',$e->getMessage());}
}
$countries=[];$countryResult=$db->query('SELECT c.*,COUNT(s.id) region_count FROM countries c LEFT JOIN states s ON s.country_id=c.id GROUP BY c.id ORDER BY (c.iso_code="IND") DESC,c.name');while($row=$countryResult->fetch_assoc())$countries[]=$row;
$editCountry=null;if(!empty($_GET['edit_country'])){$editId=(int)$_GET['edit_country'];$s=$db->prepare('SELECT * FROM countries WHERE id=?');$s->bind_param('i',$editId);$s->execute();$editCountry=$s->get_result()->fetch_assoc();}
$editRegion=null;if(!empty($_GET['edit_region'])){$editId=(int)$_GET['edit_region'];$s=$db->prepare('SELECT * FROM states WHERE id=?');$s->bind_param('i',$editId);$s->execute();$editRegion=$s->get_result()->fetch_assoc();}
$search=trim($_GET['q']??'');$countryId=max(0,(int)($_GET['country']??0));$page=max(1,(int)($_GET['page']??1));$perPage=10;$conditions=['1=1'];
if($search!==''){$safe=$db->real_escape_string($search);$conditions[]="(s.name LIKE '%$safe%' OR c.name LIKE '%$safe%')";}if($countryId)$conditions[]='s.country_id='.$countryId;$where=implode(' AND ',$conditions);
$total=(int)$db->query("SELECT COUNT(*) total FROM states s JOIN countries c ON c.id=s.country_id WHERE $where")->fetch_assoc()['total'];$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$regions=$db->query("SELECT s.*,c.name country_name,c.currency_code,COUNT(DISTINCT d.id) destinations,COUNT(DISTINCT p.id) packages FROM states s JOIN countries c ON c.id=s.country_id LEFT JOIN destinations d ON d.state_id=s.id LEFT JOIN packages p ON p.state_id=s.id WHERE $where GROUP BY s.id,c.name,c.currency_code ORDER BY c.name,s.name LIMIT $perPage OFFSET $offset");
function region_query(array $changes=[]):string{$query=array_merge(['q'=>$_GET['q']??'','country'=>$_GET['country']??''],$changes);return '?'.http_build_query(array_filter($query,static fn($v)=>$v!==''&&$v!==null));}
$pageTitle='Countries & Regions';include '_header.php';?>
<div class="page-head"><div><span>India first, international ready</span><h1>Countries &amp; Regions</h1><p>Organize destinations by country, then state, province, union territory, or territory.</p></div></div>
<div class="catalog-forms">
 <section class="panel form-panel" id="country-form"><div class="panel-head"><h2><?php echo $editCountry?'Edit country':'Add country';?></h2><?php if($editCountry):?><a href="regions.php">Cancel</a><?php endif;?></div><form class="admin-form compact-form" method="post" enctype="multipart/form-data"><?php echo csrf_input();?><input type="hidden" name="action" value="<?php echo $editCountry?'country_update':'country_create';?>"><input type="hidden" name="id" value="<?php echo (int)($editCountry['id']??0);?>"><label>Country name<input name="country_name" value="<?php echo e($editCountry['name']??'');?>" placeholder="e.g. Nepal" required></label><label>ISO code<input name="iso_code" value="<?php echo e($editCountry['iso_code']??'');?>" maxlength="3" placeholder="NPL" required></label><label>Currency code<input name="currency_code" value="<?php echo e($editCountry['currency_code']??'');?>" maxlength="3" placeholder="NPR" required></label><label>Country image <small><?php echo $editCountry?'Optional; choose a file only to replace the current image.':'Optional, JPG/PNG/WebP up to 5 MB';?></small><input type="file" name="country_image" accept="image/jpeg,image/png,image/webp"></label><div class="form-actions"><button><i class="fa-solid <?php echo $editCountry?'fa-floppy-disk':'fa-plus';?>"></i><?php echo $editCountry?'Save country':'Add country';?></button></div></form></section>
 <section class="panel form-panel" id="region-form"><div class="panel-head"><h2><?php echo $editRegion?'Edit state or territory':'Add state or territory';?></h2><?php if($editRegion):?><a href="regions.php">Cancel</a><?php endif;?></div><form class="admin-form compact-form" method="post" enctype="multipart/form-data"><?php echo csrf_input();?><input type="hidden" name="action" value="<?php echo $editRegion?'region_update':'region_create';?>"><input type="hidden" name="id" value="<?php echo (int)($editRegion['id']??0);?>"><label>Country<select name="country_id" required><option value="">Select country</option><?php foreach($countries as $c):if($c['status']!=='active'&&(!$editRegion||(int)$editRegion['country_id']!==(int)$c['id']))continue;?><option value="<?php echo (int)$c['id'];?>" <?php echo $editRegion?((int)$editRegion['country_id']===(int)$c['id']?'selected':''):($c['iso_code']==='IND'?'selected':'');?>><?php echo e($c['name']);?></option><?php endforeach;?></select></label><label>Region name<input name="name" value="<?php echo e($editRegion['name']??'');?>" required></label><label>Type<select name="type"><?php foreach(['state'=>'State','union_territory'=>'Union Territory','province'=>'Province','territory'=>'Territory'] as $value=>$label):?><option value="<?php echo $value;?>" <?php echo ($editRegion['type']??'state')===$value?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select></label><label>Region image <small><?php echo $editRegion?'Optional; choose a file only to replace the current image.':'JPG/PNG/WebP up to 5 MB';?></small><input type="file" name="region_image" accept="image/jpeg,image/png,image/webp" <?php echo $editRegion?'':'required';?>></label><div class="form-actions"><button><i class="fa-solid <?php echo $editRegion?'fa-floppy-disk':'fa-plus';?>"></i><?php echo $editRegion?'Save region':'Add region';?></button></div></form></section>
</div>
<section class="panel"><div class="panel-head"><h2>Countries</h2></div><div class="country-grid"><?php foreach($countries as $c):?><article class="country-item"><?php if($c['image']):?><img src="../<?php echo e($c['image']);?>" alt=""><?php else:?><i class="fa-solid fa-earth-asia"></i><?php endif;?><div><strong><?php echo e($c['name']);?></strong><small><?php echo e($c['iso_code']);?> &middot; <?php echo e($c['currency_code']);?> &middot; <?php echo (int)$c['region_count'];?> regions</small></div><div class="action-row"><a class="icon-btn" href="regions.php?edit_country=<?php echo (int)$c['id'];?>#country-form" title="Edit country" aria-label="Edit <?php echo e($c['name']);?>"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$c['id'];?>"><input type="hidden" name="action" value="country_<?php echo $c['status']==='active'?'disable':'enable';?>"><button class="icon-btn status-toggle <?php echo $c['status']==='active'?'is-on':'is-off';?>" title="<?php echo $c['status']==='active'?'Disable':'Enable';?> country" aria-label="<?php echo $c['status']==='active'?'Disable':'Enable';?> <?php echo e($c['name']);?>"><i class="fa-solid fa-toggle-<?php echo $c['status']==='active'?'on':'off';?>"></i></button></form><form method="post" onsubmit="return confirm('Delete this country? It must have no regions.')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$c['id'];?>"><input type="hidden" name="action" value="country_delete"><button class="icon-btn danger-icon" title="Delete country" aria-label="Delete <?php echo e($c['name']);?>"><i class="fa-solid fa-trash"></i></button></form></div></article><?php endforeach;?></div></section>
<section class="panel" id="region-results" aria-live="polite"><div class="panel-head region-tools"><div><h2>States, provinces &amp; territories</h2><small><?php echo $total;?> results</small></div><form class="search-form" id="region-search" method="get"><input type="search" name="q" value="<?php echo e($search);?>" placeholder="Search region or country" autocomplete="off"><select name="country"><option value="">All countries</option><?php foreach($countries as $c):?><option value="<?php echo (int)$c['id'];?>" <?php echo $countryId===(int)$c['id']?'selected':'';?>><?php echo e($c['name']);?></option><?php endforeach;?></select><button class="primary-btn"><i class="fa-solid fa-magnifying-glass"></i>Search</button><a class="reset-btn" href="regions.php"><i class="fa-solid fa-rotate-left"></i>Reset</a></form></div><div class="table-wrap"><table><thead><tr><th>Region</th><th>Country</th><th>Type</th><th>Destinations</th><th>Packages</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($r=$regions->fetch_assoc()):?><tr><td><div class="table-title"><img src="../<?php echo e($r['image']);?>" alt=""><strong><?php echo e($r['name']);?></strong></div></td><td><?php echo e($r['country_name']);?><small><?php echo e($r['currency_code']);?></small></td><td><?php echo e(ucwords(str_replace('_',' ',$r['type'])));?></td><td><?php echo (int)$r['destinations'];?></td><td><?php echo (int)$r['packages'];?></td><td><span class="pill"><?php echo e($r['status']);?></span></td><td><div class="action-row"><a class="icon-btn" href="regions.php?edit_region=<?php echo (int)$r['id'];?>#region-form" title="Edit region" aria-label="Edit <?php echo e($r['name']);?>"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><input type="hidden" name="action" value="<?php echo $r['status']==='active'?'disable':'enable';?>"><button class="icon-btn status-toggle <?php echo $r['status']==='active'?'is-on':'is-off';?>" title="<?php echo $r['status']==='active'?'Disable':'Enable';?> region" aria-label="<?php echo $r['status']==='active'?'Disable':'Enable';?> <?php echo e($r['name']);?>"><i class="fa-solid fa-toggle-<?php echo $r['status']==='active'?'on':'off';?>"></i></button></form><form method="post" onsubmit="return confirm('Permanently delete this unused region?')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><input type="hidden" name="action" value="delete"><button class="icon-btn danger-icon" title="Delete region" aria-label="Delete <?php echo e($r['name']);?>"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div><?php if($pages>1):?><nav class="pagination" aria-label="Region pages"><a class="<?php echo $page<=1?'disabled':'';?>" href="<?php echo e(region_query(['page'=>max(1,$page-1)]));?>"><i class="fa-solid fa-chevron-left"></i></a><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?php echo $i===$page?'active':'';?>" href="<?php echo e(region_query(['page'=>$i]));?>"><?php echo $i;?></a><?php endfor;?><a class="<?php echo $page>=$pages?'disabled':'';?>" href="<?php echo e(region_query(['page'=>min($pages,$page+1)]));?>"><i class="fa-solid fa-chevron-right"></i></a></nav><?php endif;?></section>
<script>
(()=>{let timer,controller;async function load(url){const panel=document.querySelector('#region-results');if(!panel)return;controller?.abort();controller=new AbortController();panel.classList.add('is-loading');panel.setAttribute('aria-busy','true');try{const response=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest'},signal:controller.signal});if(!response.ok)throw new Error('Search failed');const documentCopy=new DOMParser().parseFromString(await response.text(),'text/html');const incoming=documentCopy.querySelector('#region-results');if(!incoming){location.href=url;return}const currentTable=panel.querySelector('.table-wrap');const incomingTable=incoming.querySelector('.table-wrap');if(currentTable&&incomingTable)currentTable.replaceWith(incomingTable);const currentCount=panel.querySelector('.region-tools small');const incomingCount=incoming.querySelector('.region-tools small');if(currentCount&&incomingCount)currentCount.textContent=incomingCount.textContent;const currentPagination=panel.querySelector('.pagination');const incomingPagination=incoming.querySelector('.pagination');if(currentPagination&&incomingPagination)currentPagination.replaceWith(incomingPagination);else if(currentPagination)currentPagination.remove();else if(incomingPagination)panel.append(incomingPagination);history.replaceState({},'',url)}catch(error){if(error.name!=='AbortError')location.href=url}finally{panel.classList.remove('is-loading');panel.removeAttribute('aria-busy')}}function formUrl(){const form=document.querySelector('#region-search');const params=new URLSearchParams(new FormData(form));params.delete('page');for(const [key,value] of [...params])if(!value)params.delete(key);return 'regions.php'+(params.toString()?'?'+params:'')}document.addEventListener('input',event=>{if(!event.target.matches('#region-search input[name="q"]'))return;clearTimeout(timer);timer=setTimeout(()=>load(formUrl()),300)});document.addEventListener('change',event=>{if(event.target.matches('#region-search select[name="country"]'))load(formUrl())});document.addEventListener('submit',event=>{if(!event.target.matches('#region-search'))return;event.preventDefault();load(formUrl())});document.addEventListener('click',event=>{const link=event.target.closest('#region-results .pagination a, #region-results .reset-btn');if(!link||link.classList.contains('disabled'))return;event.preventDefault();if(link.classList.contains('reset-btn')){const form=document.querySelector('#region-search');form.elements.q.value='';form.elements.country.value=''}load(link.href)});})();
</script>
